    cells = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 8}
    if not cells:
        return [list(row) for row in grid]

    # Each 2x2 square is either a solid square (color 1) or an L triomino.
    # L colors encode the missing corner: TL=2, BL=3, TR=4, BR=5.
    missing_corner_color = {(0, 0): 2, (1, 0): 3, (0, 1): 4, (1, 1): 5}
    pieces = []
    height, width = len(grid), len(grid[0])
    for r in range(height - 1):
        for c in range(width - 1):
            box = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if box <= cells:
                pieces.append((box, 1))
            for (dr, dc), color in missing_corner_color.items():
                piece = box - {(r + dr, c + dc)}
                if piece <= cells:
                    pieces.append((piece, color))

    by_cell = {cell: [] for cell in cells}
    for piece, color in pieces:
        for cell in piece:
            by_cell[cell].append((piece, color))

    def solve(remaining):
        if not remaining:
            return []
        cell = min(remaining, key=lambda x: sum(piece <= remaining for piece, _ in by_cell[x]))
        for piece, color in by_cell[cell]:
            if piece <= remaining:
                rest = solve(remaining - piece)
                if rest is not None:
                    return [(piece, color)] + rest
        return None

    tiling = solve(cells)
    if tiling is None:
        # Leave the input unchanged if it does not match the demonstrated pattern.
        return [list(row) for row in grid]
    result = [list(row) for row in grid]
    for piece, color in tiling:
        for r, c in piece:
            result[r][c] = color
    return result
